        occurrence,
      } };
}

const cfg = $('Configuracion').first().json;
const t = checkTranscript(readGemini($input.first().json), cfg.maxTranscriptChars);
if (!t.hasSpeech) {
  // No hay nada que interpretar: no se crea ninguna propuesta y el trabajo NO se marca como exitoso.
  throw new Error('PERMANENTE: el audio no contiene voz inteligible; no se creó ninguna propuesta');
}
return [{ json: {
  transcript: t,
  modelVersion: $input.first().json.modelVersion ?? null,
  sttBody: {
    jobId: $('Preparar trabajo').first().json.jobId,
    claimToken: $('Preparar trabajo').first().json.claimToken,
