    // Evidencia de lo que se oyó. Nunca es aplicable: el backend rechaza aplicar una propuesta stt.
    proposedData: { transcript: t.transcript, language: t.language, uncertainFragments: t.uncertainFragments },
    evidence: { model: cfg.model, kind: 'transcripcion', audioMimeType: $('Preparar trabajo').first().json.geminiMimeType },
