// Evidencia: solo fragmentos que realmente están en el mensaje.
const evidence = (Array.isArray(raw.evidence) ? raw.evidence : [])
  .filter((e) => e && typeof e.field === 'string' && typeof e.text === 'string' && e.text.trim() !== '' && srcFold.includes(fold(e.text)))
  .slice(0, 12)
  .map((e) => ({ field: e.field.slice(0, 40), text: e.text.slice(0, 200) }));

const injection = injectionSignals(src);
const extraction = {
