return [{ json: { extraction, injection, dropped, kind: job.kind } }];

function describeQuota(detail) {
  const text = String(detail?.cause?.message ?? '') + ' ' + String(detail?.message ?? '');
  const wait = /retry in ([0-9hms.]+?)s?[.\\" ]/.exec(text)?.[1];
  const kind = /PerDay/.test(text) ? 'cuota DIARIA agotada' : /PerMinute/.test(text) ? 'límite por MINUTO alcanzado' : 'cuota o límite alcanzado';
  const limit = /quotaValue\W*(\d+)/.exec(text)?.[1];
